export type CdPage = {
  howTitle: string; how: string[];
  formulasTitle: string; formulasIntro: string; formulas: { label: string; expr: string }[]; formulasNote: string;
  exampleTitle: string; example: string;
  standardTitle: string; standardText: string[]; colTask: string;
  assumpTitle: string; assump: string[];
  faqTitle: string; faq: { q: string; a: string }[];
  linksTitle: string;
  links: { ipCams: string; ptz: string; nvr: string; calc: string; cctv: string; article: string };
};

export type CdContent = {
  /** Локаль Intl.NumberFormat: десятичный разделитель по языку. */
  numLocale: string;
  metaTitle: string; metaDesc: string;
  crumbs: { home: string; tool: string };
  /** Заголовок и одна строка под ним (редизайн 11.11: сразу под ними — рабочая область). */
  h1: string; lead: string;
  /** Силуэты уровней детализации. */
  levelsSec: { title: string; intro: string };
  /** «Как это работает» — три шага для клиента. */
  steps: { title: string; items: [string, string][] };
  /** Заголовок свёрнутого справочного блока (формулы, стандарт, допущения). */
  refTitle: string;
  ui: CdUi;
  levels: Record<LevelCode, { name: string; task: string }>;
  page: CdPage;
};

/** Формулы одинаковы на всех языках — меняются только подписи. */
const EXPR = [
  "HFOV = 2·atan(Sw / 2f)",
  "W = 2·D·tan(HFOV/2) = D·Sw / f",
  "PPM = Nx / W",
  "Dmax = Nx·f / (Sw·PPM)",
  "HFOV = 2·atan(W / 2D)",
  "Nx = ⌈W·PPM⌉",
  "D = d·cos τ + (H − h)·sin τ",
];
const withExpr = (labels: string[]) => labels.map((label, i) => ({ label, expr: EXPR[i] }));

